  state.fdDecimalRaw='0.149';state.fdLimited='12.34';
  const fdDecimalNormalize=text=>String(text).replaceAll('。','.').replaceAll('．','.');
  const fdDecimalSample=(value='0.149',limited=false)=>`<label class="f-field">小数与输入法<input data-decimal-demo ${limited?'data-decimal-limit="2"':''} inputmode="decimal" value="${esc(value)}" aria-label="小数与输入法"><small>组合输入不截断；中文/全角句号提交后规范化为小数点。范围与精度校验由业务表单负责。</small></label><p class="bc-small" data-decimal-result>当前草稿：${esc(value)}</p>`;
  fDefine('decimal-input','基础输入 · 小数与输入法','组件规范','packages/beecount_ui/lib/src/form_components.dart',()=>surface(fdDecimalSample(state.fdDecimalRaw)));
  fDefine('decimal-two-digits','基础输入 · 可选两位小数','组件规范','packages/beecount_ui/lib/src/form_components.dart',()=>surface(fdDecimalSample(state.fdLimited,true)));
  const fdDecimalGroup=document.createElement('optgroup');fdDecimalGroup.label='基础输入 · 输入法兼容';fdDecimalGroup.appendChild(new Option('小数与输入法 · 保留组合态','flow-decimal-input'));picker.appendChild(fdDecimalGroup);
  root.addEventListener('input',event=>{if(!event.target.matches('[data-decimal-demo]'))return;const raw=event.target.value;if(!event.isComposing)event.target.value=fdDecimalNormalize(raw).replace(/[^0-9.]/g,'');if(!event.isComposing&&event.target.dataset.decimalLimit)event.target.value=event.target.value.match(/^\d+\.?\d{0,2}/)?.[0]||'';if(event.target.dataset.decimalLimit)state.fdLimited=event.target.value;state.fdDecimalRaw=event.target.value;const result=event.target.closest('.bc-surface')?.querySelector('[data-decimal-result]');if(result)result.textContent='当前草稿：'+state.fdDecimalRaw;});
